-- Load seed data for schema 'logistics'.
-- Run from this folder after creating the schema:  psql -d yourdb -f load_logistics.sql
\set ON_ERROR_STOP on
BEGIN;
SET search_path TO logistics;

-- Identity columns are GENERATED ALWAYS; allow explicit ids while loading.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'logistics' AND is_identity = 'YES' AND identity_generation = 'ALWAYS' LOOP
    EXECUTE format('ALTER TABLE logistics.%I ALTER COLUMN %I SET GENERATED BY DEFAULT', r.table_name, r.column_name);
  END LOOP; END $$;

\copy clients (client_id, account_code, legal_name, tax_id, billing_email, phone, payment_terms_days, credit_limit, is_active, created_at, updated_at) FROM 'clients.csv' WITH (FORMAT csv, HEADER true)
\copy locations (location_id, client_id, name, facility_type, code, line1, line2, city, state, postal_code, country, latitude, longitude, timezone, contact_name, contact_phone, opening_hours, dock_count) FROM 'locations.csv' WITH (FORMAT csv, HEADER true)
\copy carriers (carrier_id, name, scac_code, is_own_fleet, insurance_expiry, rating) FROM 'carriers.csv' WITH (FORMAT csv, HEADER true)
\copy vehicles (vehicle_id, carrier_id, home_location_id, registration_no, vin, vehicle_type, make, model, year, max_weight_kg, max_volume_m3, is_refrigerated, hazmat_certified, status, odometer_km, updated_at) FROM 'vehicles.csv' WITH (FORMAT csv, HEADER true)
\copy vehicle_maintenance (maintenance_id, vehicle_id, maintenance_type, description, odometer_km, cost, performed_at, next_due_date, next_due_km) FROM 'vehicle_maintenance.csv' WITH (FORMAT csv, HEADER true)
\copy drivers (driver_id, carrier_id, employee_code, full_name, phone, license_number, license_class, license_expiry, hazmat_endorsed, is_active, hired_on) FROM 'drivers.csv' WITH (FORMAT csv, HEADER true)
\copy shipments (shipment_id, tracking_number, client_id, client_reference, origin_location_id, destination_location_id, service_level, status, incoterm, declared_value, currency_code, total_weight_kg, total_volume_m3, is_hazardous, requires_signature, temperature_min_c, temperature_max_c, pickup_window_start, pickup_window_end, promised_delivery_at, delivered_at, special_instructions, created_at, updated_at) FROM 'shipments.csv' WITH (FORMAT csv, HEADER true)
\copy packages (package_id, shipment_id, barcode, package_type, weight_kg, length_cm, width_cm, height_cm, description, hs_code, un_number, current_location_id) FROM 'packages.csv' WITH (FORMAT csv, HEADER true)
\copy routes (route_id, code, name, origin_location_id, destination_location_id, distance_km, standard_duration_min, is_recurring) FROM 'routes.csv' WITH (FORMAT csv, HEADER true)
\copy trips (trip_id, trip_number, route_id, vehicle_id, trailer_id, driver_id, co_driver_id, status, planned_start, planned_end, actual_start, actual_end, start_odometer_km, end_odometer_km, fuel_used_l, updated_at) FROM 'trips.csv' WITH (FORMAT csv, HEADER true)
\copy trip_stops (stop_id, trip_id, sequence_no, location_id, stop_type, planned_arrival, actual_arrival, actual_departure, notes) FROM 'trip_stops.csv' WITH (FORMAT csv, HEADER true)
\copy trip_packages (trip_id, package_id, load_stop_id, unload_stop_id, loaded_at, unloaded_at) FROM 'trip_packages.csv' WITH (FORMAT csv, HEADER true)
\copy tracking_events (event_id, shipment_id, package_id, event_code, status, location_id, trip_id, description, exception_reason, source, occurred_at, recorded_at) FROM 'tracking_events.csv' WITH (FORMAT csv, HEADER true)
\copy vehicle_positions (vehicle_id, recorded_at, latitude, longitude, speed_kmh, heading_deg, reefer_temp_c, trip_id) FROM 'vehicle_positions.csv' WITH (FORMAT csv, HEADER true)
\copy proof_of_delivery (pod_id, shipment_id, driver_id, recipient_name, signature_uri, photo_uri, latitude, longitude, delivered_at, notes) FROM 'proof_of_delivery.csv' WITH (FORMAT csv, HEADER true)
\copy rate_cards (rate_card_id, client_id, service_level, origin_zone, destination_zone, min_weight_kg, max_weight_kg, base_charge, per_kg_charge, fuel_surcharge_pct, valid_from, valid_to) FROM 'rate_cards.csv' WITH (FORMAT csv, HEADER true)
\copy invoices (invoice_id, invoice_number, client_id, status, period_start, period_end, subtotal, tax_total, grand_total, currency_code, issued_on, due_on, paid_on) FROM 'invoices.csv' WITH (FORMAT csv, HEADER true)
\copy shipment_charges (charge_id, shipment_id, charge_type, amount, rate_card_id, invoice_id) FROM 'shipment_charges.csv' WITH (FORMAT csv, HEADER true)

-- Restore GENERATED ALWAYS and move sequences past the loaded ids.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'logistics' AND is_identity = 'YES' LOOP
    EXECUTE format('SELECT setval(pg_get_serial_sequence(''logistics.%I'', %L), COALESCE((SELECT max(%I) FROM logistics.%I), 0) + 1, false)',
                   r.table_name, r.column_name, r.column_name, r.table_name);
    EXECUTE format('ALTER TABLE logistics.%I ALTER COLUMN %I SET GENERATED ALWAYS', r.table_name, r.column_name);
  END LOOP; END $$;

COMMIT;
